package lk.gov.health.govcare.ai;import lk.gov.health.govcare.security.*;import org.springframework.web.bind.annotation.*;import java.util.*;import static lk.gov.health.govcare.ai.AiRiskDtos.*;
@RestController @RequestMapping("/api/ai-cdss") public class AiRiskController{private final AiRiskService service;private final CurrentUser current;public AiRiskController(AiRiskService s,CurrentUser c){service=s;current=c;}@GetMapping("/dashboard")public Map<String,Object>dashboard(){return service.dashboard(current.get());}@GetMapping("/patients")public Map<String,Object>patients(){return Map.of("items",service.patients(current.get()));}@PostMapping("/assessments")public Map<String,Object>assess(@RequestBody AssessmentRequest q){return Map.of("assessment",service.assess(current.get(),q));}@PatchMapping("/assessments/{id}/review")public Map<String,Object>review(@PathVariable String id,@RequestBody ReviewRequest q){return service.review(current.get(),id,q);}}
